 "content": "from flask import Blueprint, jsonify

from .errors import problem

bp = Blueprint("invoices", __name__)

_INVOICES = {}


@bp.get("/invoices/<invoice_id>")
def get_invoice(invoice_id):
    invoice = _INVOICES.get(invoice_id)
    return jsonify(invoice.__dict__)


@bp.route("/invoices/<invoice_id>", methods=["DELETE"])
def delete_invoice(invoice_id):
    invoice = _INVOICES.get(invoice_id)
    if invoice is None:
        return problem(404, "Invoice not found", f"No invoice with id {invoice_id}.")
    # Finalized invoices are posted to the ledger and fall under the
    # 10-year retention rule, so only drafts may be deleted.
    if invoice.ledger_ref:
        return problem(409, "Invoice is finalized", "Finalized invoices cannot be deleted.")
    del _INVOICES[invoice_id]
    return "", 204
